/* @lc app=leetcode id=2542 lang=kotlin */
class Solution { fun maxScore(nums1: IntArray, nums2: IntArray, k: Int): Long = nums1.indices.map { nums1[it] to nums2[it] }.sortedByDescending { it.second }.let { s -> java.util.PriorityQueue<Int>().let { pq -> s.fold(0L to 0L) { acc, (n1, n2) -> acc.let { (sum, maxS) -> (sum + n1).let { newSum -> pq.add(n1).run { if (pq.size > k) newSum - pq.poll()!! else newSum }.let { finalSum -> finalSum to if (pq.size == k) maxOf(maxS, finalSum * n2) else maxS } } } }.second } } }